<?php
declare(strict_types=1);
$isHttps = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== '' && $_SERVER['HTTPS'] !== 'off';
ini_set('session.use_strict_mode','1'); session_name('coaching_tool_session');
session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']); session_start(); header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';
function overviewH(string|int|null $v): string { return htmlspecialchars((string)$v, ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$user=$_SESSION['user']??null;
if(!is_array($user)||!isset($user['id'],$user['role'])||!in_array($user['role'],['admin','coach'],true)){header('Location: ./');exit;}
$db=coachingDatabase(); $admin=$user['role']==='admin'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
if($id<1){http_response_code(400);exit('Ungültiger Klient.');}
$q=$db->prepare('SELECT k.id,k.vorname,k.nachname,k.benutzer_id,b.vorname AS coach_vorname,b.nachname AS coach_nachname FROM klienten k LEFT JOIN benutzer b ON b.id=k.benutzer_id WHERE k.id=:id'.($admin?'':' AND k.benutzer_id=:owner').' LIMIT 1');
$p=['id'=>$id]; if(!$admin)$p['owner']=(int)$user['id']; $q->execute($p); $client=$q->fetch(PDO::FETCH_ASSOC);
if(!$client){http_response_code(404);exit('Klient nicht gefunden oder kein Zugriff.');}
$token=$_SESSION['csrf_token']??''; if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$error='';$notice=isset($_GET['saved'])?'Der Klientenstatus wurde gespeichert.':'';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['status'])){
 if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}
 $st=(string)$_POST['status'];
 if(!in_array($st,['aktiv','pausiert','abgeschlossen'],true))$error='Ungültiger Status.';
 else try{$s=$db->prepare('INSERT INTO coaching_klientenstatus (klient_id,status,geaendert_von_benutzer_id) VALUES (:id,:status,:uid) ON DUPLICATE KEY UPDATE status=VALUES(status),geaendert_von_benutzer_id=VALUES(geaendert_von_benutzer_id),geaendert_am=CURRENT_TIMESTAMP');$s->execute(['id'=>$id,'status'=>$st,'uid'=>(int)$user['id']]);header('Location: client-overview.php?id='.$id.'&saved=1');exit;}catch(Throwable $e){error_log('Client status save failed: '.$e->getMessage());$error='Status nicht verfügbar. Bitte zuerst database/migrations/004_klientenstatus.sql importieren.';}
}
try{$s=$db->prepare('SELECT status FROM coaching_klientenstatus WHERE klient_id=:id');$s->execute(['id'=>$id]);$status=$s->fetchColumn()?:'aktiv';}catch(Throwable $e){$status='unbekannt';$error='Bitte einmalig database/migrations/004_klientenstatus.sql importieren.';}
$meta=$db->query('SHOW COLUMNS FROM termine')->fetchAll(PDO::FETCH_ASSOC);$cols=array_column($meta,'Field');$topic=null;foreach(['thema','titel','beschreibung'] as $candidate)if(in_array($candidate,$cols,true)){$topic=$candidate;break;}
$topicSql=$topic?'t.`'.$topic.'` AS thema':"'' AS thema";
$q=$db->prepare('SELECT t.id,t.beginn,t.dauer_minuten,t.format,t.status,'.$topicSql.' FROM termine t WHERE t.klient_id=:id ORDER BY t.beginn DESC LIMIT 100');$q->execute(['id'=>$id]);$appointments=$q->fetchAll(PDO::FETCH_ASSOC);
$goalSql='SELECT id,titel,beschreibung,erfolgskriterium,zieltermin,status,geaendert_am FROM coaching_ziele WHERE klient_id=:id'.($admin?'':' AND coach_benutzer_id=:coach').' ORDER BY geaendert_am DESC LIMIT 100';$q=$db->prepare($goalSql);$gp=['id'=>$id];if(!$admin)$gp['coach']=(int)$user['id'];$q->execute($gp);$goals=$q->fetchAll(PDO::FETCH_ASSOC);
$notes=[];$documents=[];$files=[];
if(!$admin){
 $q=$db->prepare('SELECT n.id,n.titel,n.inhalt,n.erstellt_am,n.termin_id,t.beginn FROM coaching_sitzungsnotizen n LEFT JOIN termine t ON t.id=n.termin_id WHERE n.klient_id=:id AND n.coach_benutzer_id=:coach ORDER BY n.erstellt_am DESC LIMIT 100');$q->execute(['id'=>$id,'coach'=>(int)$user['id']]);$notes=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare('SELECT id,titel,vorlage_version,status,zugewiesen_am,ausgegeben_am FROM coaching_klientendokumente WHERE klient_id=:id AND coach_benutzer_id=:coach ORDER BY zugewiesen_am DESC LIMIT 100');$q->execute(['id'=>$id,'coach'=>(int)$user['id']]);$documents=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare('SELECT f.id,f.klientendokument_id,f.version,f.originalname FROM coaching_dokumentdateien f INNER JOIN coaching_klientendokumente d ON d.id=f.klientendokument_id WHERE d.klient_id=:id AND d.coach_benutzer_id=:coach ORDER BY f.erstellt_am DESC');$q->execute(['id'=>$id,'coach'=>(int)$user['id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $f)$files[(int)$f['klientendokument_id']][]=$f;
}
$done=count(array_filter($appointments,static fn($a)=>in_array($a['status'],['abgeschlossen','stattgefunden'],true)));
$active=count(array_filter($goals,static fn($g)=>$g['status']==='aktiv'));
$open=count(array_filter($documents,static fn($d)=>in_array($d['status'],['zugewiesen','ausgegeben'],true)));
$labels=['aktiv'=>'Aktiv','pausiert'=>'Pausiert','abgeschlossen'=>'Abgeschlossen','unbekannt'=>'Nicht verfügbar'];
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Klientenakte</title><link rel="stylesheet" href="assets/layout.css"><style>
.ov{max-width:1280px;margin:auto;padding:28px clamp(18px,4vw,56px) 64px}.ovhead{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;flex-wrap:wrap}.ov h1{margin:14px 0 6px;font-size:clamp(30px,4vw,42px)}.ov p,.muted{color:#687970;line-height:1.5}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:24px 0}.stat,.card{background:#fff;border:1px solid #e4ebe6;border-radius:15px;padding:18px;box-shadow:0 8px 28px #263b320b}.stat span{display:block;color:#718078;font-size:13px}.stat strong{display:block;font-size:25px;margin:7px 0;color:#245c50}.cols{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.card{margin-bottom:16px}.card h2{font-size:18px;margin:0 0 14px}.row{padding:13px 0;border-top:1px solid #edf1ee}.row:first-of-type{border:0}.badge{display:inline-block;padding:4px 9px;border-radius:99px;background:#edf4ef;color:#35695b;font-size:12px}.meta{font-size:13px;color:#708078;margin-top:5px;line-height:1.5}.links{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-block;padding:10px 13px;border-radius:9px;background:#245c50;color:white;text-decoration:none;font-weight:650}.btn.light{background:#eef3ef;color:#35695b}.ovform{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:10px}.ovform select{padding:9px;border:1px solid #dce5df;border-radius:8px;background:#fff;font:inherit}.notice,.error{padding:12px 14px;border-radius:9px;margin:12px 0}.notice{background:#edf5ef;color:#245c50}.error{background:#fff3f1;color:#8c3434}.empty{color:#7a8981;padding:10px 0}@media(max-width:850px){.stats{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}}@media(max-width:440px){.stats{gap:8px}.stat,.card{padding:14px}}
</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'clients',$token);?><main class="ov">
<div class="ovhead"><div><a href="clients.php">← Klientenliste</a><h1><?=overviewH($client['vorname'].' '.$client['nachname'])?></h1><p>Klientenakte · <?= $admin?'Coach: '.overviewH(trim(($client['coach_vorname']??'').' '.($client['coach_nachname']??''))?:'Nicht zugeordnet'):'Deine betreute Person' ?></p></div><div class="links"><a class="btn light" href="appointments.php">Termine</a><a class="btn light" href="goals.php">Ziele</a><?php if(!$admin):?><a class="btn light" href="documents.php?klient_id=<?=$id?>">Dokumente</a><a class="btn light" href="notes.php">Private Notizen</a><?php endif;?></div></div>
<?php if($notice):?><div class="notice"><?=overviewH($notice)?></div><?php endif;?><?php if($error):?><div class="error"><?=overviewH($error)?></div><?php endif;?>
<div class="stats"><div class="stat"><span>Klientenstatus</span><strong style="font-size:20px"><?=overviewH($labels[$status]??$status)?></strong><?php if(!$admin):?><form class="ovform" method="post"><input type="hidden" name="csrf_token" value="<?=overviewH($token)?>"><label for="status">Status</label><select name="status" id="status"><option value="aktiv" <?=$status==='aktiv'?'selected':''?>>Aktiv</option><option value="pausiert" <?=$status==='pausiert'?'selected':''?>>Pausiert</option><option value="abgeschlossen" <?=$status==='abgeschlossen'?'selected':''?>>Abgeschlossen</option></select><button class="btn">Speichern</button></form><?php endif;?></div><div class="stat"><span>Sitzungen insgesamt</span><strong><?=$count=count($appointments)?></strong><span><?=$done?> abgeschlossen</span></div><div class="stat"><span>Aktive Ziele</span><strong><?=$active?></strong></div><div class="stat"><span><?= $admin?'Letzter Termin':'Offene Dokumente'?></span><strong style="font-size:18px"><?= $admin?($appointments?overviewH(date('d.m.Y',strtotime($appointments[0]['beginn']))):'—'):$open?></strong></div></div>
<div class="cols"><section><div class="card"><h2>Sitzungen und Verlauf</h2><?php if(!$appointments):?><div class="empty">Noch keine Termine vorhanden.</div><?php else:foreach($appointments as $a):?><div class="row"><strong><?=overviewH(date('d.m.Y · H:i',strtotime($a['beginn'])))?> <span class="badge"><?=overviewH($a['status'])?></span></strong><div class="meta"><?=overviewH(trim(($a['thema']??'').' · '.($a['format']??'').' · '.($a['dauer_minuten']??'').' Min.'))?></div></div><?php endforeach;endif;?></div>
<div class="card"><h2>Ziele</h2><?php if(!$goals):?><div class="empty">Noch keine Ziele angelegt.</div><?php else:foreach($goals as $g):?><div class="row"><strong><?=overviewH($g['titel'])?> <span class="badge"><?=overviewH($g['status'])?></span></strong><div class="meta"><?= $g['zieltermin']?'Zieldatum: '.overviewH(date('d.m.Y',strtotime($g['zieltermin']))):'Kein Zieldatum'?><?= $g['beschreibung']?' · '.overviewH($g['beschreibung']):''?></div></div><?php endforeach;endif;?></div></section><aside>
<?php if(!$admin):?><div class="card"><h2>Private Coach-Notizen</h2><?php if(!$notes):?><div class="empty">Noch keine privaten Notizen.</div><?php else:foreach(array_slice($notes,0,8) as $n):?><div class="row"><strong><?=overviewH($n['titel'])?></strong><div class="meta"><?=overviewH(date('d.m.Y H:i',strtotime($n['erstellt_am'])))?><?= $n['beginn']?' · Sitzung '.overviewH(date('d.m.Y',strtotime($n['beginn']))):''?><br><?=nl2br(overviewH(function_exists('mb_strimwidth')?mb_strimwidth($n['inhalt'],0,260,'…','UTF-8'):substr($n['inhalt'],0,260)))?></div></div><?php endforeach;endif;?></div>
<div class="card"><h2>Dokumente</h2><?php if(!$documents):?><div class="empty">Noch keine Dokumente zugeordnet.</div><?php else:foreach($documents as $d):?><div class="row"><strong><?=overviewH($d['titel'])?> <span class="badge"><?=overviewH($d['status'])?></span></strong><div class="meta">Zugeteilt: <?=overviewH(date('d.m.Y',strtotime($d['zugewiesen_am'])))?> · <a href="document-download.php?type=assigned-template&amp;id=<?=(int)$d['id']?>">Vorlage öffnen</a></div><?php foreach($files[(int)$d['id']]??[] as $f):?><div class="meta">Rücklauf v<?=(int)$f['version']?> · <?=overviewH($f['originalname'])?> · <a href="document-download.php?type=return&amp;id=<?=(int)$f['id']?>">Ansehen</a></div><?php endforeach;?></div><?php endforeach;endif;?></div><?php else:?><div class="card"><h2>Vertraulichkeit</h2><p>Private Notizen und Klientendokumente sind nur dem zuständigen Coach zugänglich.</p></div><?php endif;?>
</aside></div></main></body></html>